alter table public.mission365_donations add column if not exists refunded_amount_cents bigint not null default 0;
alter table public.mission365_donations add column if not exists stripe_invoice_id text;
alter table public.mission365_donations add column if not exists dispute_status text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname='mission365_donations_refunded_amount_check') then
    alter table public.mission365_donations add constraint mission365_donations_refunded_amount_check check (refunded_amount_cents >= 0 and refunded_amount_cents <= amount_cents);
  end if;
end $$;
alter table public.mission365_documents add column if not exists review_note text;
alter table public.mission365_documents add column if not exists rejection_reason text;
alter table public.mission365_missions add column if not exists submitted_at timestamptz;
alter table public.mission365_missions add column if not exists reviewed_at timestamptz;
alter table public.mission365_missions add column if not exists review_note text;
alter table public.mission365_impact_updates add column if not exists review_note text;
alter table public.mission365_milestones add column if not exists review_note text;
alter table public.mission365_payouts add column if not exists requested_by uuid;
alter table public.mission365_payouts add column if not exists requested_at timestamptz;
alter table public.mission365_payouts add column if not exists reversed_at timestamptz;
alter table public.mission365_payouts add column if not exists stripe_reversal_id text;
create table if not exists public.mission365_saved_missions (user_id uuid not null,mission_id uuid not null references public.mission365_missions(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,mission_id));
alter table public.mission365_saved_missions enable row level security;
grant select,insert,delete on public.mission365_saved_missions to authenticated;
drop policy if exists mission365_saved_missions_owner_select on public.mission365_saved_missions;create policy mission365_saved_missions_owner_select on public.mission365_saved_missions for select to authenticated using ((select auth.uid())=user_id);
drop policy if exists mission365_saved_missions_owner_insert on public.mission365_saved_missions;create policy mission365_saved_missions_owner_insert on public.mission365_saved_missions for insert to authenticated with check ((select auth.uid())=user_id and exists (select 1 from public.mission365_missions m where m.id=mission_id and m.status in ('published','funded','reporting','completed') and m.published_at is not null));
drop policy if exists mission365_saved_missions_owner_delete on public.mission365_saved_missions;create policy mission365_saved_missions_owner_delete on public.mission365_saved_missions for delete to authenticated using ((select auth.uid())=user_id);
create table if not exists public.mission365_notification_preferences (user_id uuid primary key,in_app_enabled boolean not null default true,email_enabled boolean not null default true,sms_enabled boolean not null default false,categories jsonb not null default '{"giving":true,"verification":true,"impact":true,"payouts":true,"risk":true}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.mission365_notification_preferences enable row level security;grant select,insert,update on public.mission365_notification_preferences to authenticated;
drop policy if exists mission365_notification_preferences_owner_select on public.mission365_notification_preferences;create policy mission365_notification_preferences_owner_select on public.mission365_notification_preferences for select to authenticated using ((select auth.uid())=user_id);
drop policy if exists mission365_notification_preferences_owner_insert on public.mission365_notification_preferences;create policy mission365_notification_preferences_owner_insert on public.mission365_notification_preferences for insert to authenticated with check ((select auth.uid())=user_id);
drop policy if exists mission365_notification_preferences_owner_update on public.mission365_notification_preferences;create policy mission365_notification_preferences_owner_update on public.mission365_notification_preferences for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create table if not exists public.mission365_terms_acceptances (id uuid primary key default gen_random_uuid(),user_id uuid not null,document_key text not null,version text not null,metadata jsonb not null default '{}'::jsonb,accepted_at timestamptz not null default now(),unique(user_id,document_key,version));
alter table public.mission365_terms_acceptances enable row level security;grant select,insert on public.mission365_terms_acceptances to authenticated;
drop policy if exists mission365_terms_acceptances_owner_select on public.mission365_terms_acceptances;create policy mission365_terms_acceptances_owner_select on public.mission365_terms_acceptances for select to authenticated using ((select auth.uid())=user_id);
drop policy if exists mission365_terms_acceptances_owner_insert on public.mission365_terms_acceptances;create policy mission365_terms_acceptances_owner_insert on public.mission365_terms_acceptances for insert to authenticated with check ((select auth.uid())=user_id);
create table if not exists public.mission365_business_giving_settings (organization_id uuid primary key references public.mission365_organizations(id) on delete cascade,matched_giving_enabled boolean not null default false,employee_giving_enabled boolean not null default false,match_percent numeric(6,2) not null default 100 check (match_percent >= 0 and match_percent <= 500),per_employee_limit_cents bigint not null default 0 check (per_employee_limit_cents >= 0),monthly_budget_cents bigint not null default 0 check (monthly_budget_cents >= 0),status text not null default 'draft' check (status in ('draft','active','paused')),updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.mission365_business_giving_settings enable row level security;revoke all on public.mission365_business_giving_settings from anon,authenticated;
create table if not exists public.mission365_notification_deliveries (id uuid primary key default gen_random_uuid(),notification_id uuid not null references public.mission365_notifications(id) on delete cascade,channel text not null check (channel in ('in_app','email','sms')),status text not null default 'queued' check (status in ('queued','sent','failed','skipped')),provider_message_id text,error_message text,attempted_at timestamptz,created_at timestamptz not null default now());
alter table public.mission365_notification_deliveries enable row level security;revoke all on public.mission365_notification_deliveries from anon,authenticated;
create index if not exists mission365_notification_deliveries_queue_idx on public.mission365_notification_deliveries(status,channel,created_at);create index if not exists mission365_saved_missions_user_idx on public.mission365_saved_missions(user_id,created_at desc);create index if not exists mission365_terms_acceptances_user_idx on public.mission365_terms_acceptances(user_id,accepted_at desc);
create or replace function mission365_private.apply_donation_funding_delta() returns trigger language plpgsql set search_path to 'public','pg_temp' as $$ declare old_effective bigint := 0;new_effective bigint := 0;delta bigint := 0;begin if tg_op='UPDATE' and old.status in ('succeeded','partially_refunded') then old_effective:=greatest(0,old.amount_cents-coalesce(old.refunded_amount_cents,0));end if;if new.status in ('succeeded','partially_refunded') then new_effective:=greatest(0,new.amount_cents-coalesce(new.refunded_amount_cents,0));end if;delta:=new_effective-old_effective;if delta<>0 then update public.mission365_missions set funded_amount_cents=greatest(0,funded_amount_cents+delta),updated_at=now() where id=new.mission_id;end if;return new;end;$$;
